965	  /**
966	   * Map a worker RPC error to a bridge-level error code.
967	   *
968	   * JsonRpcCallError carries numeric codes from the plugin RPC error code space.
969	   * This helper maps them to the string error codes defined in PluginBridgeErrorCode.
970	   *
971	   * @see PLUGIN_SPEC.md §19.7 — Error Propagation Through The Bridge
972	   */
973	  function mapRpcErrorToBridgeError(err: unknown): PluginBridgeErrorResponse {
974	    if (err instanceof JsonRpcCallError) {
975	      switch (err.code) {
976	        case PLUGIN_RPC_ERROR_CODES.WORKER_UNAVAILABLE:
977	          return {
978	            code: "WORKER_UNAVAILABLE",
979	            message: err.message,
980	            details: err.data,
981	          };
982	        case PLUGIN_RPC_ERROR_CODES.CAPABILITY_DENIED:
983	          return {
984	            code: "CAPABILITY_DENIED",
985	            message: err.message,
986	            details: err.data,
987	          };
988	        case PLUGIN_RPC_ERROR_CODES.TIMEOUT:
989	          return {
990	            code: "TIMEOUT",
991	            message: err.message,
992	            details: err.data,
993	          };
994	        case PLUGIN_RPC_ERROR_CODES.WORKER_ERROR:
995	          return {
996	            code: "WORKER_ERROR",
997	            message: err.message,
998	            details: err.data,
999	          };
1000	        default:
1001	          return {
1002	            code: "UNKNOWN",
1003	            message: err.message,
1004	            details: err.data,
1005	          };
1006	      }
1007	    }
1008	
1009	    const message = err instanceof Error ? err.message : String(err);
1010	
1011	    // Worker not running — surface as WORKER_UNAVAILABLE
1012	    if (message.includes("not running") || message.includes("not registered")) {
1013	      return {
1014	        code: "WORKER_UNAVAILABLE",
1015	        message,
1016	      };
1017	    }
1018	
1019	    return {
1020	      code: "UNKNOWN",
1021	      message,
1022	    };
1023	  }
