1026	   * POST /api/plugins/:pluginId/bridge/data
1027	   *
1028	   * Proxy a `getData` call from the plugin UI to the plugin worker.
1029	   *
1030	   * This is the server-side half of the `usePluginData(key, params)` bridge hook.
1031	   * The frontend sends a POST with the data key and optional params; the host
1032	   * forwards the call to the worker via the `getData` RPC method and returns
1033	   * the result.
1034	   *
1035	   * Request body:
1036	   * - `key`: Plugin-defined data key (e.g. `"sync-health"`)
1037	   * - `params`: Optional query parameters forwarded to the worker handler
1038	   *
1039	   * Response: The raw result from the worker's `getData` handler
1040	   *
1041	   * Error response body follows the `PluginBridgeError` shape:
1042	   * `{ code: PluginBridgeErrorCode, message: string, details?: unknown }`
1043	   *
1044	   * Errors:
1045	   * - 400 if request validation fails
1046	   * - 404 if plugin not found
1047	   * - 501 if bridge deps are not configured
1048	   * - 502 if the worker is unavailable or returns an error
1049	   *
1050	   * @see PLUGIN_SPEC.md §13.8 — `getData`
1051	   * @see PLUGIN_SPEC.md §19.7 — Error Propagation Through The Bridge
1052	   */
1053	  router.post("/plugins/:pluginId/bridge/data", async (req, res) => {
1054	    assertBoardOrgAccess(req);
1055	
1056	    if (!bridgeDeps) {
1057	      res.status(501).json({ error: "Plugin bridge is not enabled" });
1058	      return;
1059	    }
1060	
1061	    const { pluginId } = req.params;
1062	
1063	    // Resolve plugin
1064	    const plugin = await resolvePlugin(registry, pluginId);
1065	    if (!plugin) {
1066	      res.status(404).json({ error: "Plugin not found" });
1067	      return;
1068	    }
1069	
1070	    // Validate plugin is in ready state
1071	    if (plugin.status !== "ready") {
1072	      const bridgeError: PluginBridgeErrorResponse = {
1073	        code: "WORKER_UNAVAILABLE",
1074	        message: `Plugin is not ready (current status: ${plugin.status})`,
1075	      };
1076	      res.status(502).json(bridgeError);
1077	      return;
1078	    }
1079	
1080	    // Validate request body
1081	    const body = req.body as PluginBridgeDataRequest | undefined;
1082	    if (!body || !body.key || typeof body.key !== "string") {
1083	      res.status(400).json({ error: '"key" is required and must be a string' });
